70|    /** A Buddy chat's new run resets the same-action loop guard. */
71|    static void runStarted(String chat) {
72|        if (chat != null) STEP_COUNTS.remove(chat);
73|    }
74|
75|    static void runEnded(String chat) {
76|        if (chat != null) STEP_COUNTS.remove(chat);
77|    }
