79|    private String countStep(String name, JSONObject args) {
80|        String chat = McpServer.CALLER_CHAT.get();
81|        if (chat == null || !COUNTED_TOOLS.contains(name)) return null;
82|        StepCounter counter = STEP_COUNTS.computeIfAbsent(chat, key -> new StepCounter());
83|        String step = name + " " + args;
84|        synchronized (counter) {
85|            boolean same = step.equals(counter.last) && !REPEATS_OK.contains(name);
86|            if (counter.count >= MAX_REPEATS) {
87|                return "STOPPED by Buddy: the same action " + MAX_REPEATS
88|                        + " times in a row looks like a loop. Stop and tell the user what is done and what remains.";
89|            }
90|            counter.count = same ? counter.count + 1 : 1;
91|            counter.last = step;
92|            if (counter.count == MAX_REPEATS) {
93|                return "STOPPED by Buddy: the same action " + MAX_REPEATS
94|                        + " times in a row looks like a loop. Stop and tell the user what is done and what remains.";
95|            }
96|        }
97|        return null;
98|    }
