100|    /** Start the standalone MCP server only when Buddy's Accessibility service is off. */
101|    static void ensure(Context context) {
102|        Intent intent = new Intent(context, RootMcpService.class);
103|        if (SetupState.accessibilityEnabled(context)) {
104|            context.stopService(intent);
105|            return;
106|        }
107|        if (Build.VERSION.SDK_INT >= 26) context.startForegroundService(intent);
108|        else context.startService(intent);
109|    }
