165|    void showRuntimeStatus(String status) {
166|        if (!active) return;
167|        NotificationManager manager = getSystemService(NotificationManager.class);
168|        if (manager != null && manager.areNotificationsEnabled()) {
169|            String safe = status == null ? "Browsing" : status;
