573|    private JSONObject confirm(JSONObject args) throws Exception {
574|        String summary = args.getString("summary").trim();
575|        if (summary.isEmpty()) throw new IllegalArgumentException("Give the exact action to approve.");
576|        if (summary.length() > 500) throw new IllegalArgumentException("Approval summaries are limited to 500 characters.");
577|        String chat = McpServer.CALLER_CHAT.get();
578|        boolean rule = Triggers.ruleRun(chat);
579|        String foreground = RootControl.foregroundPackage();
580|        if (!rule && Guard.autonomous(this, foreground)) {
581|            return text("APPROVED automatically: the user trusts " + foreground
582|                    + ", so work there without calling confirm. Apps on Hard or Smart still ask the user.");
583|        }
584|        if (!rule && Guard.routineText(summary) && Guard.runRule(this, foreground)) {
585|            Guard.approved(summary, true);
586|            noteInChat(chat, R.string.run_rule_approved, summary);
587|            return text("APPROVED by the user's rule for this run: routine steps are allowed in " + foreground
588|                    + " without asking. This approval covers sending only; paying, buying, deleting, installing, "
589|                    + "passwords and security settings still need the user's OK.");
590|        }
591|        int countdown = rule ? Triggers.countdown(chat) : 0;
592|        boolean instant = rule && Triggers.instant(chat);
593|        String shown = summary;
594|        if (countdown > 0 || instant) {
595|            showRuntimeStatus(getString(R.string.rules_status_checking));
596|            String objection = Triggers.review(this, chat, summary);
597|            if (objection != null) {
598|                countdown = 0;
599|                instant = false;
600|                shown = getString(R.string.tools_card_detail, summary, objection);
601|            }
602|        }
603|        if (instant) {
604|            noteInChat(chat, R.string.card_note_rule_approved, summary);
605|            Guard.approved(summary, true);
606|            return text(BuddyService.RULE_APPROVED);
607|        }
608|        if (rule && countdown == 0 && Triggers.locked(this)) return text(BuddyService.NOT_NOW);
609|        long timeout = rule ? (countdown + 60L) * 1000L : Math.max(5 * 60_000L, (countdown + 60L) * 1000L);
610|        String approval = RootApproval.request(this, "Approve this action?\n" + shown, timeout,
611|                countdown > 0 ? countdown * 1000L : 0);
612|        if ("APPROVED".equals(approval) || "AUTO_APPROVED".equals(approval)) {
613|            boolean automatic = "AUTO_APPROVED".equals(approval);
614|            Guard.approved(summary, automatic);
615|            return text(automatic ? BuddyService.AUTO_APPROVED : "APPROVED by the user. Go ahead.");
616|        }
617|        if (rule) return text(BuddyService.NOT_NOW);
618|        return text("NO APPROVAL: " + approval + ". Do not proceed.");
619|    }
