621|    private JSONObject ask(JSONObject args) throws Exception {
622|        String question = args.getString("question").trim();
623|        JSONArray choices = args.getJSONArray("options");
624|        if (question.isEmpty()) throw new IllegalArgumentException("Give a question.");
625|        if (question.length() > 200) throw new IllegalArgumentException("Questions are limited to 200 characters.");
626|        if (choices.length() < 2 || choices.length() > 4) throw new IllegalArgumentException("Give 2 to 4 answer choices.");
627|        java.util.ArrayList<String> options = new java.util.ArrayList<>();
628|        for (int i = 0; i < choices.length(); i++) {
629|            String option = choices.optString(i).trim();
630|            if (option.isEmpty() || option.length() > 40) throw new IllegalArgumentException("Each answer must contain 1 to 40 characters.");
631|            if (!options.contains(option)) options.add(option);
632|        }
633|        if (options.size() < 2) throw new IllegalArgumentException("Give at least two different answer choices.");
634|        String chat = McpServer.CALLER_CHAT.get();
635|        boolean rule = Triggers.ruleRun(chat);
636|        if (rule && Triggers.locked(this)) return text(BuddyService.NOT_NOW);
637|        long timeout = rule ? 60_000L : 5 * 60_000L;
638|        JSONArray browserHighlight = args.optJSONArray("browser_highlight");
639|        if (browserHighlight != null && browserHighlight.length() > 0) {
640|            if (rule) return text("The background browser is not available in a notification rule's run. Ask the user to do this step on the phone.");
641|            return text(askInBrowser(question, options, browserHighlight, timeout));
642|        }
643|        JSONArray highlight = args.optJSONArray("highlight");
644|        boolean showingMarks = highlight != null && highlight.length() > 0;
645|        if (showingMarks && Background.on(this, chat)) {
646|            return text("Coordinate highlights are not available while this chat's Background mode is on. Turn it off, then retry ask.");
647|        }
648|        if (!showingMarks) {
649|            String answer = RootApproval.requestChoice(this, question, options, timeout);
650|            return text(answer == null || answer.isEmpty()
651|                    ? "NO ANSWER: notifications are unavailable or the user did not answer within "
652|                            + (rule ? "a minute" : "5 minutes") + "."
653|                    : "ANSWER: “" + answer + "”");
654|        }
655|        java.util.ArrayList<RootMarksOverlay.Mark> marks = coordinateMarks(highlight);
656|        synchronized (marksLock) {
657|            requireUnlocked("ask");
658|            if (!ensureOverlayPermission()) return text("Android overlay settings are open. Enable Display over other apps for Buddy, then call ask again.");
659|            if (marksOverlay == null) marksOverlay = new RootMarksOverlay(this);
660|            marksOverlay.show(marks, "box", timeout);
661|            try {
662|                String answer = RootApproval.requestChoice(this, question, options, timeout);
663|                return text(answer == null || answer.isEmpty()
664|                        ? "NO ANSWER: notifications are unavailable or the user did not answer within "
665|                                + (rule ? "a minute" : "5 minutes") + "."
666|                        : "ANSWER: “" + answer + "”");
667|            } finally {
668|                if (marksOverlay != null) {
669|                    try { marksOverlay.clear(); } catch (Exception ignored) { }
670|                }
671|            }
672|        }
673|    }
