706|    private String askInBrowser(String question, java.util.List<String> options, JSONArray items, long timeoutMs) throws Exception {
707|        String key = Browser.key(McpServer.CALLER_CHAT.get());
708|        if (!Browser.available(this) || !Browser.running() || !Browser.hasTab(key)) {
709|            return "The background browser has no page open for this chat: call browser_open first, or use coordinate highlight.";
710|        }
711|        JSONArray marks = new JSONArray();
712|        for (int i = 0; i < items.length() && marks.length() < 6; i++) {
713|            JSONObject item = items.optJSONObject(i);
714|            if (item != null && item.has("ref")) {
715|                marks.put(new JSONObject().put("ref", item.getInt("ref")).put("label", item.optString("label")));
716|            }
717|        }
718|        if (marks.length() == 0) return "Give browser_highlight as [{\"ref\": 12, \"label\": \"Your password\"}].";
719|        Browser.setMarks(key, marks);
720|        try {
721|            JSONArray boxes = Browser.markBoxes(key, true);
722|            for (int i = 0; boxes != null && i < boxes.length(); i++) {
723|                if (boxes.isNull(i)) {
724|                    return "There's no item [" + marks.getJSONObject(i).getInt("ref")
725|                            + "] on the page now. Call browser_read again.";
726|                }
727|            }
728|            Intent open = new Intent(this, BrowserActivity.class).putExtra("key", key)
729|                    .putExtra("guided", true);
730|            String answer = RootApproval.requestChoice(this, question, options, open, timeoutMs);
731|            return answer == null || answer.isEmpty()
732|                    ? "NO ANSWER: notifications are unavailable or the user did not answer within 5 minutes."
733|                    : "ANSWER: “" + answer + "”";
734|        } finally {
735|            Browser.setMarks(key, null);
736|            Browser.touched(key);
737|        }
738|    }
