989|        String pkg = args.getString("package").trim();
990|        if (pkg.isEmpty()) throw new IllegalArgumentException("Give the Android package name.");
991|        long before = installedVersion(pkg);
992|        long requested = Math.max(0, args.optLong("min_version_code", 0));
993|        long need = requested > 0 ? requested : (before < 0 ? 0 : before + 1);
994|        int timeout = (int) Math.max(10, Math.min(300, args.optInt("timeout_s", 120)));
995|        long start = android.os.SystemClock.elapsedRealtime();
996|        while (true) {
997|            long version = installedVersion(pkg);
998|            if (version >= 0 && version >= need) {
999|                return text("Installed " + pkg + " (versionCode " + version + "). Android PackageManager confirms the package is present.");
1000|            }
1001|            long elapsed = android.os.SystemClock.elapsedRealtime() - start;
1002|            if (elapsed >= timeout * 1000L) {
1003|                return text("TIMED OUT after " + timeout + " s: " + pkg + " has not reached versionCode " + need
1004|                        + ". The user may not have confirmed the install.");
1005|            }
1006|            Thread.sleep(1000);
1007|        }
